"""Build report and two-page thesis from completed frozen v4 measurements."""
import json
from pathlib import Path
from pypdf import PdfReader
from build_learned_report import block,pdf,docx,ST

ROOT=Path(__file__).resolve().parents[1]
BASE=ROOT/'experiments/evidence/instance_v4'; VIDEO=ROOT/'experiments/evidence/davis_v4'
OUT=ROOT/'output/research_instance_v4'


def read(path): return json.loads(path.read_text(encoding='utf-8'))
def pct(x): return '—' if x is None else f'{100*x:.2f}'


def main():
    OUT.mkdir(parents=True,exist_ok=True)
    labels=read(BASE/'labels.json'); rows=read(BASE/'test_summary.json');frozen=read(BASE/'frozen_thresholds.json');stats=read(BASE/'statistics.json')
    mainrows={r['method']:r for r in rows if r['delta']==.02}; names=['visual_baseline','visual_strict','gate_text_s2027_full']
    video={r['method']:r for r in read(VIDEO/'summary.json') if r['subset']=='main_eval'}
    minimum=frozen['settings']['0.02']['recall_minimum']; verify=read(BASE/'verification.json')
    result='Заранее заданные условия подтверждающего сравнения выполнены на этой выборке.' if stats['confirmatory_success'] else 'Заранее заданные условия подтверждения преимущества текста не выполнены.'
    a=mainrows[names[1]];b=mainrows[names[2]]
    headline=f'Строгий визуальный контроль: полнота {pct(a["tpr"])}%, FPR {pct(a["fpr"])}%. Текстовый фильтр: полнота {pct(b["tpr"])}%, FPR {pct(b["fpr"])}%. '+result
    detail=f'Снижение риска относительно строгого контроля: {stats["risk_reduction_vs_strict"]:.4f} на пару; 95% парный bootstrap по категориям [{stats["risk_ci95"][0]:.4f}; {stats["risk_ci95"][1]:.4f}]. Изменение полноты относительно исходного визуального метода: {100*stats["recall_change_vs_original"]:.2f} п.п.; интервал [{100*stats["recall_ci95"][0]:.2f}; {100*stats["recall_ci95"][1]:.2f}] п.п.'
    def table(selected):
        return [['Метод','R %','FPR %','P %','5FP+FN']]+[[labels[n],pct(mainrows[n]['tpr']),pct(mainrows[n]['fpr']),pct(mainrows[n]['precision']),5*mainrows[n]['fp']+mainrows[n]['fn']] for n in selected]
    B=[]
    def add(kind,text=None,**kw):B.append(block(kind,text,**kw))
    add('title','Проверка текстового фильтра при ограниченной потере полноты')
    add('p','В. О. Шабашев. Отчёт от 11 октября 2026 года. Новая независимая по экземплярам оценка и перенос на видео. Цена ложного принятия 5:1, допустимая потеря полноты 2 процентных пункта утверждены до эксперимента.')
    add('p',headline);add('p',detail)
    add('table',rows=table(names),widths=[225,60,60,60,60])
    add('image',path=BASE/'primary_results.png',height=210)
    add('small','Основной тест: 320 пар, 40 новых физических экземпляров. Полнота и FPR оценивают принятие готовых вырезок, не локализацию рамки.')
    add('break');add('head','Новые данные и независимость')
    add('p','Washington RGB-D: 80 ранее не использованных физических ID, 40 validation и 40 test, 20 категорий и 400 изображений. Единственный референс — первый кадр первого видео; четыре кандидата — заранее заданные позиции другого видео. В каждой категории две цели сравниваются с восемью кандидатами своего split: 4 positive и 4 negative на запрос. Разбиение не пересекается с 184 обучающими ID.')
    add('p','Категории включают яблоки, бананы, телефоны, расчёски, консервы, стаканчики продуктов, полотенца, клавиатуры, лампочки, лаймы, лук, апельсины, тарелки, плоскогубцы, ластики, ножницы, губки, степлеры, зубные щётки и бутылки. Новые экземпляры выбраны по алфавитно-равномерному правилу до вычисления признаков. Это разные видео одного стенда, а не независимые фоновые сцены.')
    add('p','DAVIS 2017: первые 20 последовательностей по алфавиту из официального val.txt используются как новый тест нашего проекта. Выбраны до двух ID первого кадра, всего 29 запросов. Эталон — RGB-вырезка первого кадра, первый кадр исключён. Для основной оценки выбраны восемь равномерных кадров каждого видео: 232 решения, из них только четыре без видимой аннотации цели. Для двух первых видео добавлены все кадры, всего с дополнением 393 решения и 261 уникальный кадр.')
    add('p','Идентичность DAVIS задана внутри видео; физическое непересечение объектов между всеми видео не гарантировано. Встречаются сходные локации и мероприятия. Поэтому 20 видео не объявляются 20 доказанными независимыми съёмками. Пересечение с предобучением кодировщиков неизвестно. Здания как цели не проверены. Синтетические наблюдения не добавлялись.')
    add('p','RGB-D разрешает некоммерческое исследовательское/образовательное использование; DAVIS указывает CC BY-NC 4.0 в метаданных набора, новые аннотации — CC BY 4.0. URL, CRC и SHA256 сохранены; исходные изображения и веса не включены в Git. Рамки DAVIS получены из масок видимых пикселей [xmin,ymin,xmax+1,ymax+1], преобразование проверено тестом и визуально.')
    add('break');add('head','Метод и честный визуальный контроль')
    add('p','DINOv2-small с косинусом формирует визуальную оценку. Qwen3.5:0.8b независимо описывает эталон и кандидата; MiniLM кодирует описания. Использован исходный авторский MLP из mahalanobis-concept-drift: 384→256→128→64, BatchNorm/GELU/dropout. Три текстовых проектора обучены с seed 2027/2028/2029; основной seed=2027 определён заранее.')
    add('p','Обучение: 112 старых GMOT ID и все 72 старых RGB-D ID, 920 изображений. Batch-hard triplet с L2-нормированным выходом, margin 0,2, Adam 0,001, 30 эпох. Новые validation/test ID не входят в обучение или ковариацию. Полная ковариация Ledoit–Wolf оценивается по симметричным разностям train-пар одного ID с добавлением 10⁻⁴I. На одинаковых MLP-признаках сравнивается косинус.')
    add('image',path=ROOT/'experiments/evidence/instance_v3/mahalanobis_formula.png',height=40)
    add('p','Эмпирический риск на пару: R=(5FP+FN)/N при доле положительных пар 1/2. Чувствительность к другой частоте цели: R(c,π)=c(1−π)FPR+πFNR. Увеличение цены FP не оправдывает постоянный отказ: дополнительно ограничивается полнота.')
    add('p',f'Исходный порог DINO выбран по максимальному macro-F1 на валидации: R0={pct(frozen["validation_baseline_recall"])}%. Из него до test получено численное ограничение R_min=R0−2 п.п.={pct(minimum)}%. Ужесточённый визуальный порог и условный текст минимизируют 5FP+FN при одной и той же минимальной полноте. SIFT не используется для завышения ориентира.')
    add('p','Текст применяется только к визуально принятым неоднозначным парам; граница — один из четырёх заранее заданных квантилей validation-расстояний. Его отключение допускается. При отсутствии описания сохраняется визуальное решение. Все пороги зафиксированы коммитом до test. Допуски 0, 1 и 5 п.п. — дополнительные варианты, также откалиброванные до test; они не заменяют основной при неудаче.')
    add('p','Подтверждение требует снижения FPR относительно строгого визуального контроля, положительной нижней границы интервала снижения риска, нижней границы изменения полноты относительно исходного метода не ниже −2 п.п. и средней полноты не ниже R_min. Это новая гипотеза; прежний p=0,125 сюда не переносится.')
    add('break');add('head','Результаты всех фиксированных вариантов')
    add('table',rows=table(list(mainrows)),widths=[225,60,60,60,60])
    add('small','R, FPR и precision усреднены по 20 категориям. Все строки с текстом — фильтры поверх исходного DINO. Последний столбец — суммарная цена ошибок по 320 парам. Дополнительные метрики и seed не используются для выбора победителя по тесту.')
    add('image',path=BASE/'confusion.png',height=200)
    add('p',detail)
    add('p','При основном допуске стоимость ошибок снизилась с 621 до 582, то есть на 6,28%. Относительно строгого контроля текст отклонил 13 ложных совпадений, но принял четыре других; итоговое уменьшение FP равно девяти. Потеряны шесть правильных совпадений. Полнота упала на 3,75 п.п., что превышает утверждённый допуск 2 п.п. Уже исходный визуальный метод на test имеет полноту 83,75%, ниже validation-ориентира 89,25%: абсолютный порог полноты не перенёсся на новые экземпляры.')
    add('p','Полная ковариация с seed2027 дала на пять FP меньше, чем косинус на том же проекторе, но потеряла ещё три TP. Seed2029 повторил суммарные счётчики основного варианта; seed2028 дал стоимость 637, хуже строгого визуального контроля 621. Поэтому устойчивое превосходство метрики и обучения не установлено. При дополнительном допуске 0 п.п. текст сократил FP на два без потери TP; этот заранее заданный вторичный результат не заменяет основной тест и требует новой подтверждающей выборки.')
    add('p','Интервалы получены совместной перевыборкой категорий, 10 000 повторов, seed2027. 320 пар не рассматриваются как 320 независимых объектов. Невыполнение критерия не доказывает равенства методов; положительный точечный эффект без требуемой границы интервала не объявляется подтверждённым превосходством.')
    add('break');add('head','Устойчивость к допуску и различимость признаков')
    add('image',path=BASE/'recall_tolerance.png',height=215)
    add('small','Ось допуска относится к выбору на validation; фактическая потеря полноты на test может быть больше. Пороги после теста не исправляются.')
    add('image',path=BASE/'roc_pr.png',height=215)
    add('small','ROC/PR одиночных расстояний объединяют пары (micro). Кресты — фиксированные рабочие точки трёх систем; условная система не изображается как одно пороговое расстояние. Кривые не используются для выбора новых порогов.')
    add('break');add('head','Обучение и геометрия признаков')
    add('image',path=BASE/'training.png',height=155)
    add('image',path=BASE/'distances.png',height=170)
    add('image',path=BASE/'tsne.png',height=165)
    add('small','t-SNE — описательное двумерное отображение, не доказательство качества и не способ выбора конфигурации. Низкая обучающая потеря также не доказывает обобщение.')
    add('break');add('head','Перенос на полные кадры видео')
    vrows=[['Метод','TP','FP','FN','R %','IoU','Риск']]+[[labels[n],video[n]['tp'],video[n]['fp'],video[n]['fn'],pct(video[n]['macro']['recall']),f'{video[n]["macro"]["mean_iou"]:.3f}',f'{video[n]["macro"]["risk"]:.3f}'] for n in names]
    add('table',rows=vrows,widths=[185,35,35,35,55,55,65])
    add('small','Счётчики по 232 решениям; R, IoU и риск — macro по 20 видео. TP требует IoU≥0,5. Неправильная рамка при наличии цели даёт FP+FN; пропуск имеет IoU=0. Это не официальная оценка сегментации DAVIS.')
    add('image',path=BASE/'video_results.png',height=210)
    add('p',f'Правильная рамка среди предложений YOLOv8n: macro-полнота {pct(video[names[0]]["macro"]["proposal_recall"])}%. Кандидаты и выбор ближайшего DINO одинаковы у трёх методов. Пороги перенесены из RGB-D validation. Начальная рамка на видео модели не предоставляется, но эталон извлечён из первого кадра, поэтому условия легче отдельной съёмки.')
    add('p','При четырёх случаях отсутствия видимой цели FPR отсутствия не имеет достаточной точности для обобщения. Отсутствие маски не доказывает физического отсутствия за перекрытием. Принятие другого экземпляра отдельно учитывается лишь при перекрытии с рамкой другого размеченного ID; остальные ошибки могут быть ошибками локализации.')
    add('p','Относительно строгого визуального контроля получено на три ложные выдачи рамки меньше (27→24) и на одну правильную меньше (142→141). Ошибки принятия другого размеченного ID уменьшились с 22 до 20. Macro-полнота снизилась на 0,33 п.п., а риск — с 0,7469 до 0,7031. Это описательный перенос с малым числом изменённых решений; статистически устойчивое преимущество на видео не заявляется.')
    add('p','Два непрерывных демонстрационных видео выбраны до предсказаний: bike-packing и blackswan. Для них отдельно сохранены эпизоды ложной выдачи рамки, потери и восстановления. Покадровый повторный поиск не объявляется новым трекером или доказанным улучшением оптического потока. Дополнительные кадры не увеличивают основную выборку 232 решений.')
    add('p','На непрерывных видео нет переходов от отсутствия видимой цели к её появлению, поэтому задержка повторного обнаружения не оценена. Число эпизодов ложной выдачи не изменилось: два для каждой цели bike-packing, ноль для blackswan. Уменьшение количества ошибочных кадров не означает устранение целых эпизодов.')
    add('break');add('head','Результаты по отдельным последовательностям')
    sequence_rows=[r for r in read(VIDEO/'per_sequence.json') if r['subset']=='main_eval']
    lookup={(r['scene'],r['method']):r for r in sequence_rows}
    sequence_table=[['Видео','R исход. %','R строг. %','R текст %','FP исход.','FP строг.','FP текст']]
    for scene in sorted({r['scene'] for r in sequence_rows}):
        sequence_table.append([scene]+[pct(lookup[(scene,n)]['recall']) for n in names]+[lookup[(scene,n)]['fp'] for n in names])
    add('table',rows=sequence_table,widths=[135,55,55,55,55,55,55])
    add('small','Таблица по основным восьми кадрам каждого видео и выбранным запросам. Английские названия — исходные идентификаторы DAVIS. Соседние кадры и запросы одного видео зависимы.')
    add('image',path=BASE/'per_category.png',height=195)
    add('small','Изменение риска по категориям основного теста RGB-D. Положительное значение означает пользу текста относительно более строгого визуального порога.')
    add('break');add('head','Затраты и воспроизводимость')
    add('image',path=BASE/'latency.png',height=230)
    add('p',f'Независимый пересчёт: {verify["pair_decisions"]} парных и {verify["video_decisions"]} видео-решений, статус {verify["status"]}. Проверены непересечение train/validation/test ID, хеши протокола, счётчики, риск 5FP+FN и координатный IoU. Это программная перепроверка в том же проекте, не независимая лабораторная репликация.')
    add('p','CPU Intel i5-1240P, 8 ГБ RAM, четыре потока. Модели запускались последовательно; кэш описаний сохранён. Время стадий не является онлайн FPS: описания для сравнения вырезок подготовлены заранее. RSS дерева процесса может не включать внешний Ollama; снимок свободной памяти зависит и от других приложений. Обработка больших моделей не объявляется работой в реальном времени.')
    add('p',result+' Научный вклад — контролируемая проверка дополнительной текстовой информации при одинаковом бюджете полноты, адаптация исходного MLP и измеренный перенос на другие экземпляры/видео. DINO, triplet loss, Ledoit–Wolf и сама архитектура не объявляются новыми. Универсальный выигрыш Махаланобиса, работа на любых объектах и зданиях требуют отдельных доказательств.')
    refs=[
        '[1] Lai K., Bo L., Ren X., Fox D. A Large-Scale Hierarchical Multi-View RGB-D Object Dataset. ICRA, 2011. https://rgbd-dataset.cs.washington.edu/',
        '[2] Pont-Tuset J. et al. The 2017 DAVIS Challenge on Video Object Segmentation. arXiv:1704.00675. https://davischallenge.org/davis2017/code.html',
        '[3] Perazzi F. et al. A Benchmark Dataset and Evaluation Methodology for Video Object Segmentation. CVPR, 2016.',
        '[4] Oquab M. et al. DINOv2: Learning Robust Visual Features without Supervision. arXiv:2304.07193, 2023.',
        '[5] Hermans A., Beyer L., Leibe B. In Defense of the Triplet Loss for Person Re-Identification. arXiv:1703.07737, 2017.',
        '[6] Ledoit O., Wolf M. A well-conditioned estimator for large-dimensional covariance matrices. J. Multivariate Analysis, 88(2), 2004, 365–411.',
        '[7] Шабашев В. О. Mahalanobis Concept Drift Detector. https://github.com/sha-bash/mahalanobis-concept-drift; исходная реализация MLP.']
    add('head','Источники')
    for ref in refs:add('small',ref)
    add('break');add('head','Что установлено и что проверять дальше')
    add('p','Подтверждено наблюдением: текст меняет решения сверх простого ужесточения визуального порога и на двух новых наборах уменьшает число ложных принятий. На RGB-D точечная стоимость ошибок снизилась на 6,28%, но согласованный предел потери полноты нарушен. На DAVIS снижение ошибок получено без новой калибровки, однако изменённых решений слишком мало для общего вывода. Строгое утверждение о полезном превосходстве при допуске 2 п.п. не подтверждено; равенство методов также не доказано.')
    add('p','Отдельно о текстовом модуле: в основном RGB-D тесте он запрошен для 138 из 320 пар. Среди них 58 истинных совпадений: 52 приняты, 6 отклонены; из 80 чужих экземпляров 67 приняты, 13 отклонены. Условная полнота проверки 89,66%, доля отсечённых чужих экземпляров 16,25%. Эти числа относятся только к неоднозначным визуально принятым парам и не являются качеством модуля на всей выборке.')
    add('image',path=BASE/'cost_sensitivity.png',height=195)
    add('p','Дополнительная чувствительность рассчитана при неизменных решениях для цены FP 1/2/5/10 и доли цели 0,1/0,5/0,9. Это пересчёт риска, не новые наблюдения. При изменении частоты цели меняется полезность фильтра; результаты сбалансированных пар нельзя прямо объявлять эксплуатационной точностью.')
    add('head','Следующий подтверждающий эксперимент')
    add('p','1. Использовать раскрытый тест только для разработки. Следующую проверку провести на новых физических экземплярах с эталоном из отдельной съёмки, трудными отрицательными примерами, отсутствием цели и полными эпизодами выхода/возврата. Разделять по экземплярам и съёмкам; близкие видео одной локации объединять в статистический кластер.')
